CREATE OR REPLACE FUNCTION public.resolve_tile_contests(_world uuid DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE request_row record; world_row worlds%ROWTYPE; n integer:=0; BEGIN IF auth.uid() IS NOT NULL AND(_world IS NULL OR NOT is_world_member(auth.uid(),_world)) THEN RAISE EXCEPTION 'Not a world member'; END IF; FOR world_row IN SELECT world_record.* FROM worlds world_record WHERE(_world IS NULL OR world_record.id=_world) AND EXISTS(SELECT 1 FROM tile_requests due WHERE due.world_id=world_record.id AND due.kind='contest' AND due.status='pending' AND due.deadline_game_hour<=extract(epoch FROM(now()-world_record.created_at))/3600*24) ORDER BY world_record.id FOR UPDATE LOOP FOR request_row IN SELECT * FROM tile_requests WHERE world_id=world_row.id AND kind='contest' AND status='pending' AND deadline_game_hour<=extract(epoch FROM(now()-world_row.created_at))/3600*24 FOR UPDATE LOOP IF world_row.map_data->'tiles'->request_row.tile_y->request_row.tile_x->>'claimedBy'=request_row.owner_id::text AND is_world_member(request_row.requester_id,world_row.id) THEN UPDATE tile_requests SET status='expired' WHERE id=request_row.id; UPDATE worlds SET map_data=jsonb_set(map_data,ARRAY['tiles',request_row.tile_y::text,request_row.tile_x::text,'claimedBy'],to_jsonb(request_row.requester_id::text)) WHERE id=world_row.id; n:=n+1; ELSE UPDATE tile_requests SET status='cancelled' WHERE id=request_row.id; END IF; END LOOP; END LOOP; RETURN n; END $$;